1	/**
2	 * Guards RFC-0001 v3: every local markdown reference must resolve. For each link
3	 * in the autopilot skills/agents, docs/, rfc/, README.md, and CONTRIBUTING.md whose
4	 * target is repo-local (a relative path or a bare `#anchor`, not an external URL or a
5	 * `<placeholder>`), this asserts the target file exists and — when the link carries a
6	 * heading anchor into a markdown file — that the anchor matches a real heading (using
7	 * GitHub's slug algorithm). Fenced code blocks and the inlined `ref-format` block are
8	 * excluded: the links inside them are illustrative specimens, not references.
9	 */
10	import { existsSync, statSync } from "node:fs";
11	import { readFile } from "node:fs/promises";
12	import { dirname, join, resolve } from "node:path";
13	
14	import { describe, expect, test } from "bun:test";
15	
16	import { walkMarkdown } from "./markdownFiles";
17	
18	const actionDir = join(import.meta.dirname, "..");
19	const repoRoot = join(actionDir, "..", "..", "..");
20	
21	const sourceDirs = [
22	  "claude-plugins/autopilot/skills",
23	  "claude-plugins/autopilot/agents",
24	  "docs",
25	  "rfc",
26	];
27	const sourceRootFiles = ["README.md", "CONTRIBUTING.md"];
28	
29	/** Drop fenced code blocks, honouring CommonMark fences of any length (3+ ` or ~). */
30	function stripFences(s: string): string {
31	  const out: string[] = [];
32	  let fence: { char: string; len: number } | null = null;
33	  for (const line of s.split("\n")) {
34	    const open = /^\s*(`{3,}|~{3,})/.exec(line);
35	    const isBareFence = /^\s*(`{3,}|~{3,})\s*$/.test(line);
36	    if (!fence) {
37	      if (open) fence = { char: open[1][0], len: open[1].length };
38	      else out.push(line);
39	    } else if (open && isBareFence && open[1][0] === fence.char && open[1].length >= fence.len) {
40	      fence = null;
41	    }
42	  }
43	  return out.join("\n");
44	}
45	
46	const stripRefBlock = (s: string): string =>
47	  s.replace(/<!-- ref-format:start -->[\s\S]*?<!-- ref-format:end -->/g, "");
48	
49	/** Drop inline-code spans so a whole link rendered as a code specimen is not treated as a reference. */
50	const stripInlineCode = (s: string): string => s.replace(/`[^`\n]*`/g, "");
51	
52	const linkPattern = /\[[^\]]*\]\(([^)\s]+)\)/g;
53	
54	/** Repo-local link targets only: skip external schemes, `<placeholders>`, empty anchors. */
55	function isLocalTarget(target: string): boolean {
56	  if (!target || target === "#") return false;
57	  if (/^[a-z][a-z0-9+.-]*:/i.test(target)) return false;
58	  if (target.includes("<") || target.includes(">")) return false;
59	  return true;
60	}
61	
62	/** GitHub heading-anchor slug: lowercase, drop punctuation/emoji, spaces → hyphens, de-dupe. */
63	function slugify(headingText: string, seen: Map<string, number>): string {
64	  let s = headingText.replace(/\[([^\]]*)\]\([^)]*\)/g, "$1");
65	  s = s.replace(/[`*_~]/g, "");
66	  s = s.trim().toLowerCase();
67	  s = s.replace(/[^\p{L}\p{N}\s-]/gu, "");
68	  s = s.replace(/\s/g, "-");
69	  const count = seen.get(s) ?? 0;
70	  seen.set(s, count + 1);
71	  return count === 0 ? s : `${s}-${count}`;
72	}
73	
74	const anchorCache = new Map<string, Set<string>>();
75	async function anchorsFor(file: string): Promise<Set<string>> {
76	  const cached = anchorCache.get(file);
77	  if (cached) return cached;
78	  const anchors = new Set<string>();
79	  const seen = new Map<string, number>();
80	  let content: string;
81	  try {
82	    content = await readFile(file, "utf8");
83	  } catch {
84	    anchorCache.set(file, anchors);
85	    return anchors;
86	  }
87	  for (const line of stripFences(content).split("\n")) {
88	    const heading = /^#{1,6}\s+(.*?)\s*#*\s*$/.exec(line);
89	    if (heading) anchors.add(slugify(heading[1], seen));
90	    for (const id of line.matchAll(/<a\s+id="([^"]+)"/g)) {
91	      anchors.add(id[1]);
92	      anchors.add(id[1].toLowerCase());
93	    }
94	  }
95	  anchorCache.set(file, anchors);
96	  return anchors;
97	}
98	
99	interface Reference {
100	  label: string;
101	  sourceFile: string;
102	  filePath: string;
103	  anchor: string | null;
104	}
105	
106	const sourceFiles = [
107	  ...(await Promise.all(sourceDirs.map((d) => walkMarkdown(join(repoRoot, d))))).flat(),
108	  ...sourceRootFiles.map((f) => join(repoRoot, f)).filter((f) => existsSync(f)),
109	];
110	
111	const references: Reference[] = [];
112	for (const sourceFile of sourceFiles) {
113	  const body = stripInlineCode(stripRefBlock(stripFences(await readFile(sourceFile, "utf8"))));
114	  for (const match of body.matchAll(linkPattern)) {
115	    const target = match[1];
116	    if (!isLocalTarget(target)) continue;
117	    const hashIndex = target.indexOf("#");
118	    const pathPart = hashIndex === -1 ? target : target.slice(0, hashIndex);
119	    const anchor = hashIndex === -1 ? null : target.slice(hashIndex + 1);
120	    const filePath = pathPart === "" ? sourceFile : resolve(dirname(sourceFile), pathPart);
121	    const rel = sourceFile.slice(repoRoot.length + 1);
122	    references.push({ label: `${rel} → ${target}`, sourceFile, filePath, anchor });
123	  }
124	}
125	
126	describe("link resolution (RFC-0001 v3)", () => {
127	  test("found a meaningful number of local references to validate", () => {
128	    expect(references.length).toBeGreaterThan(50);
129	  });
130	
131	  test.each(references)("$label", async ({ filePath, anchor }) => {
132	    expect(existsSync(filePath)).toBe(true);
133	    if (anchor && filePath.endsWith(".md") && statSync(filePath).isFile()) {
134	      const anchors = await anchorsFor(filePath);
135	      expect(anchors.has(anchor) || anchors.has(anchor.toLowerCase())).toBe(true);
136	    }
137	  });
138	});
