1	/**
2	 * Markdown discovery shared by the repository guard tests.
3	 *
4	 * The guards (`linkResolution`, `planFileOutputPurity`) all start the same way: walk a
5	 * source directory and collect every `.md` file, so their coverage comes from the
6	 * filesystem rather than a hardcoded list. That discovery is the load-bearing property —
7	 * it is what makes a newly added skill or reference file guarded without editing a test —
8	 * so it lives in one place instead of being copied per guard.
9	 *
10	 * @example
11	 * const files = await walkMarkdown(join(repoRoot, "claude-plugins/autopilot/skills"));
12	 */
13	import { readdir } from "node:fs/promises";
14	import { join } from "node:path";
15	
16	/**
17	 * Every `.md` file under `dir`, recursively.
18	 *
19	 * Returns `[]` for a directory that cannot be read, so a guard listing an optional source
20	 * directory (`rfc/` in a repo that has none) degrades to "nothing to check" instead of
21	 * throwing. Bundled dependencies are skipped: the `pdf:create` skill vendors a `renderer/`
22	 * whose package READMEs carry package-relative links that do not resolve in this tree.
23	 */
24	export async function walkMarkdown(dir: string): Promise<string[]> {
25	  // `.catch(() => null)` rather than a try/catch around an annotated binding: annotating it
26	  // as `Awaited<ReturnType<typeof readdir>>` picks the Buffer overload, so every `entry.name`
27	  // then types as NonSharedBuffer instead of string.
28	  const entries = await readdir(dir, { withFileTypes: true }).catch(() => null);
29	  if (!entries) return [];
30	  const out: string[] = [];
31	  for (const entry of entries) {
32	    if (entry.isDirectory() && entry.name === "node_modules") continue;
33	    const full = join(dir, entry.name);
34	    if (entry.isDirectory()) out.push(...(await walkMarkdown(full)));
35	    else if (entry.isFile() && entry.name.endsWith(".md")) out.push(full);
36	  }
37	  return out;
38	}
